"""
Batch-capable, reversal-aware trend extraction for one-dimensional signals.

The returned samples correspond to original indices window_size - 1 onward.
"""
import numpy as np

try:
    from scipy.signal import savgol_filter
    _HAVE_SCIPY = True
except Exception:
    savgol_filter = None
    _HAVE_SCIPY = False


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1 or x.size < window_size:
        raise ValueError(
            f"Input signal length ({x.size}) must be >= window_size ({window_size})"
        )
    return np.convolve(x, np.ones(window_size, dtype=float) / window_size, "valid")


def _finite_signal(x):
    z = np.asarray(x, dtype=float).copy()
    good = np.isfinite(z)
    if not np.any(good):
        return np.zeros_like(z)
    if not np.all(good):
        ind = np.arange(z.size)
        z[~good] = np.interp(ind[~good], ind[good], z[good])
    return z


def _robust_sigma(v):
    v = np.asarray(v, dtype=float)
    if v.size == 0:
        return np.finfo(float).eps
    med = float(np.median(v))
    return max(1.4826 * float(np.median(np.abs(v - med))),
               np.finfo(float).eps)


def _median3(z):
    if z.size < 3:
        return z.copy()
    p = np.pad(z, (1, 1), mode="edge")
    return np.median(np.stack((p[:-2], p[1:-1], p[2:])), axis=0)


def _odd_span(requested, n, minimum=5):
    if n < minimum:
        return 1
    maximum = n if n % 2 else n - 1
    span = min(maximum, max(minimum, int(requested)))
    if span % 2 == 0:
        span -= 1
    return max(minimum, span)


def _savgol_estimate(z, span):
    z = np.asarray(z, dtype=float)
    if span <= 1 or z.size < 5:
        return z.copy()

    span = _odd_span(span, z.size)
    half = span // 2
    order = min(3, span - 1)

    if _HAVE_SCIPY and savgol_filter is not None:
        return np.asarray(savgol_filter(z, span, order, mode="mirror"), dtype=float)

    u = np.arange(-half, half + 1, dtype=float)
    design = np.column_stack([u ** k for k in range(order + 1)])
    weights = np.linalg.pinv(design)[0]
    padded = np.pad(z, (half, half), mode="reflect")
    return np.convolve(padded, weights[::-1], mode="valid")


def _local_candidate(z, window_size):
    n = z.size
    if n < 5:
        return z.copy()

    spans = []
    for requested in (
        max(5, window_size + 1),
        max(7, 2 * window_size + 1),
        max(9, 3 * window_size + 1),
    ):
        span = _odd_span(requested, n)
        if span > 1 and span not in spans:
            spans.append(span)

    raw_noise = _robust_sigma(np.diff(z))
    choices = []
    for span in spans:
        fit = _savgol_estimate(z, span)
        choices.append((_robust_sigma(z - fit), fit))

    acceptable = [fit for residual, fit in choices
                  if residual >= 0.35 * raw_noise]
    return acceptable[-1] if acceptable else choices[0][1]


def _turn_indices(y):
    d = np.diff(y)
    if d.size < 2:
        return []

    s = np.sign(d).astype(np.int8)
    last = np.int8(0)
    for i in range(s.size):
        if s[i] == 0:
            s[i] = last
        else:
            last = s[i]

    last = np.int8(0)
    for i in range(s.size - 1, -1, -1):
        if s[i] == 0:
            s[i] = last
        else:
            last = s[i]

    return [i for i in range(1, s.size) if s[i - 1] * s[i] < 0]


def _project_short_turns(candidate, residual_sigma, window_size):
    y = np.asarray(candidate, dtype=float).copy()
    n = y.size
    if n < 5:
        return y

    sigma = max(float(residual_sigma), np.finfo(float).eps)
    short = max(4, window_size // 2)

    for _ in range(n):
        turns = _turn_indices(y)
        if not turns:
            break

        knots = [0] + turns + [n - 1]
        removed = False
        for j in range(1, len(knots) - 1):
            a, k, b = knots[j - 1], knots[j], knots[j + 1]
            width = b - a
            if width < 2:
                continue

            frac = (k - a) / float(width)
            chord = y[a] + frac * (y[b] - y[a])
            prominence = abs(y[k] - chord)
            threshold = sigma * (0.55 + 0.16 * np.sqrt(width))

            if (width <= short and prominence < 1.35 * threshold) or (
                prominence < 0.45 * sigma
            ):
                y[a:b + 1] = np.linspace(y[a], y[b], width + 1)
                removed = True
                break

        if not removed:
            break

    y[0] = candidate[0]
    y[-1] = candidate[-1]
    return y


def _robust_linear_fit(design, target):
    weights = np.ones(target.size, dtype=float)
    coef = None
    eps = np.finfo(float).eps

    for _ in range(3):
        try:
            coef, _, _, _ = np.linalg.lstsq(
                design * weights[:, None], target * weights, rcond=None
            )
        except (np.linalg.LinAlgError, ValueError, FloatingPointError):
            return None

        residual = target - design @ coef
        scale = max(_robust_sigma(residual), eps)
        q = np.abs(residual) / (1.5 * scale)
        weights = np.where(q <= 1.0, 1.0, 1.0 / q)

    fitted = design @ coef
    return fitted if np.all(np.isfinite(fitted)) else None


def _harmonic_lattice_candidate(z, local):
    """
    Search bases with q cycles per record and harmonics h*q.
    This differs from a standard DFT-order trend by allowing the fundamental
    itself to move across a small deterministic model bank.
    """
    n = z.size
    if n < 24:
        return None

    t = np.arange(n, dtype=float)
    u = (t - 0.5 * (n - 1)) / max(float(n - 1), 1.0)
    centered = z - np.median(z)
    raw_scale = _robust_sigma(z - _median3(z))
    eps = np.finfo(float).eps

    spectrum = np.abs(np.fft.rfft(centered)) ** 2
    upper_bin = min(max(2, n // 8), spectrum.size - 1)
    fft_choices = []
    if upper_bin >= 1:
        order = np.argsort(spectrum[1:upper_bin + 1])[-4:] + 1
        fft_choices = [int(v) for v in order]

    bases = sorted(set([1, 2, 3, 4, 5, 6, 7, 8] + fft_choices))
    best = None
    best_score = np.inf
    best_turns = None
    local_turns = len(_turn_indices(local))

    for q in bases:
        if q < 1 or q > n // 8:
            continue

        max_h = min(10, max(1, n // max(6 * q, 1)))
        columns = [np.ones(n), u]
        for h in range(1, max_h + 1):
            phase = 2.0 * np.pi * float(h * q) * t / float(n)
            columns.extend((np.cos(phase), np.sin(phase)))

        design = np.column_stack(columns)
        fitted = _robust_linear_fit(design, z)
        if fitted is None:
            continue

        residual = z - fitted
        scale = _robust_sigma(residual)
        if scale < 0.20 * raw_scale:
            continue

        rss = float(np.dot(residual, residual))
        bic = n * np.log(max(rss / n, eps)) + design.shape[1] * np.log(n)
        turns = len(_turn_indices(fitted))

        # A modest structural surcharge favors low-reversal global trends.
        score = bic + 0.5 * np.log(n) * turns
        if score < best_score:
            best_score = score
            best = fitted
            best_turns = turns

    if best is None:
        return None

    local_mae = float(np.median(np.abs(z - local)))
    model_mae = float(np.median(np.abs(z - best)))
    if (model_mae <= 1.45 * max(local_mae, eps) and
            best_turns <= local_turns + 1):
        return best
    return None


def _step_candidate(z, window_size):
    """Conservative one-step reconstruction used only for strong plateaus."""
    n = z.size
    if n < max(8, 2 * window_size):
        return None

    smooth = _savgol_estimate(z, _odd_span(max(5, window_size // 2 * 2 + 1), n))
    d = np.diff(smooth)
    sigma = _robust_sigma(d)
    if sigma <= np.finfo(float).eps:
        return None

    jump = int(np.argmax(np.abs(d))) + 1
    if abs(d[jump - 1]) < 6.0 * sigma:
        return None

    margin = max(3, window_size // 3)
    if jump < margin or n - jump < margin:
        return None

    left = float(np.median(z[:jump]))
    right = float(np.median(z[jump:]))
    if abs(right - left) < 4.0 * sigma:
        return None

    result = np.empty(n, dtype=float)
    result[:jump] = left
    result[jump:] = right
    return result


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1 or x.size < window_size:
        raise ValueError(
            f"Input signal length ({x.size}) must be >= window_size ({window_size})"
        )

    z = _finite_signal(x)
    if z.size <= 3:
        return z[window_size - 1:].copy()

    robust = _median3(z)
    local = _local_candidate(robust, window_size)
    candidate = local

    harmonic = _harmonic_lattice_candidate(robust, local)
    if harmonic is not None:
        candidate = harmonic

    step = _step_candidate(z, window_size)
    if step is not None:
        local_residual = np.median(np.abs(z - candidate))
        step_residual = np.median(np.abs(z - step))
        if step_residual <= 1.20 * max(local_residual, np.finfo(float).eps):
            candidate = step

    if candidate.size != z.size or not np.all(np.isfinite(candidate)):
        candidate = local

    residual_sigma = _robust_sigma(z - candidate)
    filtered = _project_short_turns(candidate, residual_sigma, window_size)
    if not np.all(np.isfinite(filtered)):
        filtered = candidate

    return filtered[window_size - 1:].copy()


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    noisy_signal = clean_signal + rng.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = window_size - 1
    aligned_clean = clean_signal[delay:delay + len(filtered_signal)]
    aligned_noisy = noisy_signal[delay:delay + len(filtered_signal)]
    m = min(len(filtered_signal), len(aligned_clean))

    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0:
        correlation = float(np.corrcoef(filtered_signal, aligned_clean)[0, 1])
    else:
        correlation = 0.0

    noise_before = float(np.var(aligned_noisy - aligned_clean))
    noise_after = float(np.var(filtered_signal - aligned_clean))
    noise_reduction = (
        (noise_before - noise_after) / noise_before if noise_before > 0 else 0.0
    )

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": noise_reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

